INSERT INTO Language_ko_KR (Tag, Text)
VALUES	('TXT_KEY_BUILDING_ARCADE',			'오락실'),
		('TXT_KEY_BUILDING_ARCADE_TEXT',		'오락실은 사람들이 아케이드 비디오 게임, 핀볼 머신, 전자기계 게임, 보상 게임, 판매대(예: 크레인 인형), 동전으로 작동하는 당구대 또는 에어 하키대 등의 아케이드 게임을 즐길 수 있는 장소입니다. 일부 국가에서는 일부 유형의 아케이드에서 슬롯머신이나 파친코 머신과 같은 도박 기계를 제공하는 것이 합법적으로 허용됩니다. 게임은 대개 캐비닛에 내장됩니다. 비디오 게임은 1970년대 후반에 오락실에 처음 소개되었으며, 아케이드 비디오 게임의 황금기인 1980년대 초반에 가장 인기를 끌었습니다.[NEWLINE][NEWLINE]1900년대 초반에 동전을 넣어 작동하는 간단한 기계 장치를 갖춘 페니 아케이드에서 유래되었습니다. 여기에는 현재 현대 카지노 건물의 대부분을 차지하고 있는 가장 초기의 슬롯머신이 포함되었습니다. 이후 게임은 전자기계식으로 바뀌었고, 마침내 팩맨, 스페이스 인베이더, 퐁 등의 게임으로 완전히 컴퓨터화되었습니다. 1990년대에는 모탈 컴뱃과 같은 멀티플레이어 격투 게임과 NFL 블리츠와 같은 스포츠 게임이 인기를 얻었습니다. 결국 컴퓨터 하드웨어의 발전으로 최초의 가정용 콘솔이 출시되었고, 오락실의 인기는 급격히 감소했습니다. 오늘날 콘솔은 다이브 바, 카지노, 그 외에 베팅 시설에서만 볼 수 있습니다.'),
		('TXT_KEY_BUILDING_ARCADE_STRATEGY',	'오락실은 문화 승리에 대한 마지막 방어선입니다. 건물은 두 가지 방법으로 이를 달성합니다. 첫째, 외국 관광에 맞서 문화를 생산하며, 오락실이 도움을 주는 더 많은 기술을 발견하면 문화를 강화할 수 있습니다. 두 번째로, 무료로 인한 불행을 없애는데, 그렇지 않으면 외국 관광이 일정 비율로 증가할 것입니다. 당신은 다른 방법으로 승리할 때까지 버틸 수 있을까요? 아니면 당신의 사람들은 적의 청바지를 입고 살게 될까요?'),
		('TXT_KEY_BUILDING_ARCADE_HELP',		'도시에 새로운 [ICON_CITIZEN] 시민이 태어나면 [ICON_RESEARCH] 과학 35를 받습니다. (시대에 따라 보정) 새로운 기술을 해제하면 [ICON_CULTURE] 문화 100을 얻습니다. (시대에 따라 보정) [COLOR_CYAN]인터넷[ENDCOLOR]이 발견되면 [ICON_GOLD] 골드, [ICON_RESEARCH] 과학, [ICON_CULTURE] 문화가 +8만큼 증가합니다.[NEWLINE][NEWLINE][ICON_CULTURE] 무료로 인한 [ICON_HAPPINESS_3] 불행이 없습니다.');